head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
// 선택 상태를 API 값과 화면에서 선택 표시된 아이템 양쪽으로 출력
scwin.printState = function (strPrefix) {
    var objComp = $p.getComponentById("target1");
    var arrRow = objComp.render.querySelectorAll("tr.w2multiselect_tr_over");
    var arrSelected = [];

    for (var i = 0; i < arrRow.length; i++) {
        arrSelected.push((arrRow[i].textContent || "").trim());
    }

    scwin.setReturnValue(strPrefix + " getSelectedIndex() : '" + objComp.getSelectedIndex() + "'"
        + " / getValue() : '" + objComp.getValue() + "'"
        + " / 화면에서 선택 표시된 아이템 : [" + arrSelected.join(", ") + "]");
};

scwin.btn_run_onclick = function (e) {
    var objComp = $p.getComponentById("target1");

    objComp.setSelectedIndex("1,2");
    scwin.printState("[1차 setSelectedIndex('1,2') 후]");

    objComp.setSelectedIndex("1,2");
    scwin.printState("[2차 setSelectedIndex('1,2') 후]");
};
